INSERT INTO Faqs (Question, Answer, Category, IsActive, CreatedAt, UpdatedAt) VALUES
(N'mèo có ăn được khoai lang không', N'Khoai lang hấp chín không gia vị an toàn một ít bạn nhé! Nhưng mèo là động vật ăn thịt không cần tinh bột. Cho ăn ít thỉnh thoảng không thành vấn đề nhé! 🍠', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo già có cần chơi không', N'Vẫn cần bạn nhé! Nhưng ít và nhẹ nhàng hơn. Đồ chơi chuyển động chậm puzzle đồ ăn. Tránh nhảy cao leo trèo nhiều vì khớp yếu. 10-15 phút chơi nhẹ ngày giúp tinh thần bé tươi tắn nhé! 🧸', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'nước mèo uống mỗi ngày bao nhiêu là đủ', N'Mèo cần khoảng 50-60ml nước mỗi kg cân nặng mỗi ngày bạn nhé! Mèo ăn hạt khô cần uống nhiều hơn mèo ăn wet food. Nước hơi ấm nhẹ một số bé thích hơn nước lạnh nhé! 💧', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có mèo Russian Blue không?', N'Có bạn nhé! Mèo Russian Blue tại shop giá 6-10 triệu. Lông xám xanh ánh bạc nhút nhát lúc đầu nhưng trung thành. Bạn muốn biết thêm không? 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo anh có ngoan không', N'Mèo Anh Lông Ngắn rất ngoan và dễ chăm bạn nhé! Điềm tĩnh, không hung hăng, thích nằm một chỗ quan sát. Ít kêu, không phá đồ nếu có đủ đồ chơi. Rất hợp nhà có trẻ em nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo rụng lông nhiều phải làm sao', N'Rụng lông theo mùa là bình thường. Chải lông thường xuyên. Rụng thành mảng da đỏ ngứa thì đưa đi khám vì có thể do nấm da bạn nhé! 🪮', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N't muốn tặng mèo làm quà sinh nhật có được không', N'Tặng mèo làm quà có thể rất đặc biệt nhưng cần cân nhắc kỹ bạn nhé. Người nhận cần thực sự muốn nuôi mèo và có điều kiện chăm sóc lâu dài. Thay vì tặng mèo trực tiếp, bạn có thể tặng phiếu mua mèo để người đó tự chọn bé phù hợp, hoặc đi cùng đến shop chọn mèo làm món quà trải nghiệm nhé! 🎁', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo con mấy tuần thì cai sữa được', N'Cai sữa tốt nhất lúc 8-10 tuần tuổi bạn nhé! Quá sớm trước 6 tuần có thể gây vấn đề hành vi và hệ miễn dịch yếu. Không nên tách mèo con khỏi mẹ trước 8 tuần nhé! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Abyssinian mèo Abys sống bao lâu', N'Mèo Abyssinian mèo Abys trung bình sống 12-16 năm với chăm sóc tốt bạn nhé! Giá tại shop 6-12 triệu. Lông ngắn mướt hoạt động nhiều thông minh rất tò mò và năng động nhé! 🎂', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Maine Coon ăn hạt gì tốt', N'Mèo Maine Coon nên ăn hạt chất lượng phù hợp tuổi bạn nhé! Royal Canin có dòng riêng cho một số giống. Minino giá phải chăng phù hợp hàng ngày. Giá bé 8-18 triệu tại shop. Shop tư vấn thêm nhé! 🌾', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Hàng bị vỡ khi vận chuyển thì sao?', N'Nếu đơn hàng bị hư hỏng do lỗi vận chuyển, shop sẽ hoàn tiền 100% hoặc gửi lại hàng miễn phí nhé bạn. Vui lòng chụp ảnh/video lúc nhận hàng và liên hệ shop trong vòng 24 giờ sau khi nhận để được hỗ trợ nhanh nhất! 📸', N'shipping', 1, GETUTCDATE(), GETUTCDATE()),
(N'scottish fold có đau vì tai cụp không', N'Một số có thể bị đau khớp do đột biến gen ảnh hưởng sụn bạn nhé! Chọn bé có tai cụp vừa phải không quá phẳng từ shop uy tín chọn lọc kỹ. Giá 6-12 triệu tại Meow Garden nhé! 🐱', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay rên khi ngủ là sao', N'Hoàn toàn bình thường bạn nhé! Mèo rên khi ngủ sâu REM đang mơ săn mồi. Giống hệt người nói mê. Chỉ lo nếu mèo thức dậy vẫn rên hoặc rên khi bị chạm vào vì đó là dấu hiệu đau nhé! 💤', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Tại sao mèo hay lật đồ vật xuống sàn?', N'Mèo lật đồ xuống sàn vì: tò mò và khám phá, thử nghiệm vật lý (xem điều gì xảy ra), muốn thu hút sự chú ý của chủ, hoặc đơn giản là vì thấy vui. Hành vi này phổ biến nhất khi mèo chán và thiếu kích thích. Chơi đùa nhiều hơn với bé sẽ giảm hành vi này đáng kể nhé! 😂', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo bị sốt phải làm gì?', N'Nhiệt độ bình thường của mèo là 38-39.5°C. Trên 39.5°C là sốt bạn nhé. Dấu hiệu mèo sốt: lờ đờ, không ăn, tai và chân nóng hơn bình thường, run. Không cho mèo uống thuốc hạ sốt của người vì rất độc với mèo! Đưa đi khám ngay để điều trị đúng cách! 🌡️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'chat với nhân viên thật ở đâu', N'Nhắn qua fanpage Facebook hoặc Zalo OA Meow Garden để gặp nhân viên thật bạn nhé! MeowBot tự động 24/7, nhân viên người thật trong giờ 8h-21h nhé! 😊', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo con ăn hạt hay pate tốt hơn', N'Kết hợp 50% pate mềm và 50% hạt kitten ngâm mềm bạn nhé! 🍼', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'thanh toán bằng hình thức nào', N'COD thanh toán khi nhận hàng và chuyển khoản ngân hàng có QR tự động bạn nhé! 💳', N'order', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có thể bị cô đơn không', N'Có bạn nhé! Mặc dù mèo độc lập nhưng vẫn cần tương tác xã hội. Vắng nhà thường xuyên nên nuôi thêm bé thứ 2, để TV hoặc nhạc nhẹ, dùng camera xem bé từ xa nhé! 🏠', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mua cá vàng ở đâu', N'Meow Garden chuyên mèo cảnh, không có cá cảnh bạn nhé! Nhưng nếu bạn muốn tìm bạn đồng hành lông xù thì mình sẵn sàng tư vấn nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'đi công tác dài ngày mèo nhờ ai trông', N'Pet sitter đến nhà mỗi ngày là tốt nhất bạn nhé! Mèo không thích môi trường lạ. Để lại đủ thức ăn nước sạch, hướng dẫn người trông về thói quen của bé. Nhắn thăm hỏi thường xuyên nhé! 🏡', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị rụng lông nhiều sau sinh là sao', N'Mèo cái sau sinh thường rụng lông nhiều do thay đổi hormone bạn nhé! Thường tự hết sau 2-3 tháng khi hormone ổn định. Đảm bảo dinh dưỡng đủ cho cả mèo mẹ và con bú nhé! 🍼', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'vợ tôi sắp sinh muốn mua mèo có được không', N'Được bạn nhé nhưng cần lưu ý bạn nhé! Mẹ bầu không nên dọn khay cát, rửa tay sau khi chạm mèo. Nếu mèo đã được kiểm tra Toxoplasma âm tính thì hoàn toàn an toàn. Nhiều gia đình có cả mèo và em bé nhỏ vui lắm nhé! 🤰', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'ALN giá bao nhiêu?', N'Mèo Anh Lông Ngắn tại shop:
• ALN xám xanh: 4.5 triệu
• ALN bicolor: 6.5 triệu
• ALN golden: 8 triệu
Giá có thể thay đổi theo giới tính và độ tuổi nhé bạn! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay gãi tai là bị gì', N'Thường do ghẻ tai có bụi đen trong tai, nhiễm nấm men, hoặc nhiễm khuẩn tai. Dùng dung dịch vệ sinh tai chuyên dụng và đưa đi khám để chỉ định thuốc đúng nhé bạn! 👂', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Anh Lông Ngắn ALN bicolor nuôi có khó không?', N'Mèo Anh Lông Ngắn ALN bicolor lông chia 2 màu đối xứng rất đẹp tính cách điềm tĩnh. Giá 6.5 triệu. Về độ khó chăm sóc hãy hỏi thêm mình tư vấn cụ thể nhé bạn! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Anh Lông Ngắn ALN golden bao lâu tắm một lần', N'Mèo Anh Lông Ngắn ALN golden tắm 1 lần tháng là đủ bạn nhé! Lông vàng rực rỡ cao cấp đang rất được săn đón. Lông ngắn dễ chăm hơn. Giá bé 8 triệu nhé! 🛁', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'giao hàng mất mấy ngày', N'Nội thành HN HCM: 1-2 ngày. Tỉnh lân cận: 2-3 ngày. Tỉnh xa: 3-5 ngày làm việc bạn nhé! 🚚', N'shipping', 1, GETUTCDATE(), GETUTCDATE()),
(N'có thể dùng lò sưởi cho mèo không', N'Được nhưng cẩn thận bạn nhé! Mèo rất thích nằm gần nguồn nhiệt. Đảm bảo bé không thể chạm trực tiếp vào bộ phận nóng. Dùng ổ sưởi điện thú cưng chuyên dụng an toàn hơn lò sưởi thông thường nhé! 🔥', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bỏ ăn 2 ngày phải làm sao', N'Bỏ ăn 48h cần đưa đi khám ngay bạn ơi! Mèo bỏ ăn lâu có thể dẫn đến gan nhiễm mỡ nguy hiểm. Thử hâm nóng pate để kích thích ăn trong khi chờ khám nhé! 🏥', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'không biết', N'Không sao bạn nhé! Bạn cứ kể tình huống hoặc nhu cầu hiện tại, mình sẽ tư vấn phù hợp nhất cho bạn nhé! 😊', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo bị ghẻ tai làm sao?', N'Dấu hiệu: lắc đầu liên tục, gãi tai, có bụi đen trong tai. Dùng dung dịch vệ sinh tai chuyên dụng nhỏ vào tai, massage gốc tai rồi để mèo lắc ra. Nếu nặng cần dùng thuốc diệt ký sinh trùng theo chỉ định bác sĩ thú y, không tự ý mua thuốc nhé! 👂', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'Lược chải lông mèo Furminator dùng như thế nào?', N'Lược chải lông mèo Furminator loại bỏ lông chết tận gốc giảm rụng lông đến 90%. Giá 250.000đ. Bạn muốn biết thêm cách sử dụng không? 😊', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Tôi muốn mua Cát đậu nành Tofu Cature 6L', N'Bạn chọn đúng rồi! Cát đậu nành Tofu Cature 6L an toàn nếu mèo nuốt ít bụi thân thiện môi trường. Giá 120.000đ tại shop. Đặt hàng trên website nhé! 🛒', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo sợ sấm sét tiếng nổ phải làm sao', N'Tạo nơi ẩn náu an toàn trong tủ hoặc phòng tối bạn nhé! Không bồng bế hay an ủi quá nhiều vì dễ reinforcing sự sợ hãi. Cân nhắc dùng Feliway, áo Thundershirt, hoặc trao đổi với bác sĩ về thuốc giảm lo âu nhẹ nhé! 🌩️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'cát mèo loại nào tốt nhất', N'Cát đậu nành Tofu: an toàn nhất cho mèo con 120k/6L. Cát thủy tinh: khử mùi tốt nhất 150k/5L. Cát bentonite: rẻ nhất nhưng nhiều bụi. Shop có cả 3 loại bạn nhé! 🏆', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'có thể thay đổi địa chỉ giao hàng sau khi đặt không', N'Được khi đơn chưa giao bạn nhé! Liên hệ shop ngay qua fanpage Zalo để đổi địa chỉ. Sau khi đã lấy hàng thì không đổi được nhé! 📍', N'shipping', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có bán Xẻng xúc cát vệ sinh không?', N'Có bạn nhé! Xẻng xúc cát vệ sinh giá 20.000đ. Cần thiết để xúc vón cát hàng ngày. 🛍️', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị ngộ độc phải làm sao', N'Đưa đến bác sĩ thú y NGAY LẬP TỨC, mang theo thứ mèo đã ăn. Không tự gây nôn trừ khi bác sĩ hướng dẫn nhé bạn! 🚨', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo bị phân trắng là bị gì?', N'Phân mèo trắng hoặc có đốm trắng thường do giun sán bạn nhé đặc biệt là giun đũa hoặc sán dải. Cần tẩy giun ngay và đưa đi khám để xét nghiệm phân xác định loại ký sinh trùng và dùng thuốc phù hợp. Tẩy giun định kỳ 2-3 tháng giúp phòng ngừa hiệu quả! 💊', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bao nhiêu kg là béo', N'Hầu hết mèo ở 4-5kg là lý tưởng, trên 6kg là thừa cân bạn nhé! 🍖', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Cát thủy tinh khử mùi 5L dùng như thế nào?', N'Cát thủy tinh khử mùi 5L khử mùi tốt nhất thay ít hơn các loại khác. Giá 150.000đ. Bạn muốn biết thêm cách sử dụng không? 😊', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'TNR là gì', N'TNR là Trap-Neuter-Return - bắt, triệt sản, thả lại bạn nhé! Phương pháp quản lý mèo hoang bền vững nhất. Triệt sản ngăn mèo sinh sản, thả về lãnh thổ giảm xung đột. Nhiều hội nhóm ở VN đang làm TNR nhé! ✂️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'cách phòng bệnh cho mèo', N'Phòng bệnh cho mèo: tiêm vaccine đúng lịch, tẩy giun định kỳ, khám thú y 6 tháng một lần, dinh dưỡng cân bằng, vệ sinh khay cát hàng ngày, tránh tiếp xúc mèo lạ bạn nhé! 💉', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'Bán mèo Ragdoll không?', N'Có bạn nhé! Mèo Ragdoll giá 6-12 triệu. Siêu hiền mềm xìu khi bế không cào cắn hợp gia đình trẻ em. Liên hệ shop để xem bé nhé! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Nhà cây cho mèo cat tree 120cm dùng như thế nào?', N'Nhà cây cho mèo cat tree 120cm đáp ứng nhu cầu leo trèo cào móng và ngủ nghỉ giảm phá đồ trong nhà. Giá 850.000đ. Bạn muốn biết thêm cách sử dụng không? 😊', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có gây dị ứng không', N'Khoảng 10-15% người bị dị ứng mèo bạn nhé, do protein Fel d 1 trong nước bọt da chết và nước tiểu mèo. Nếu bạn lo ngại thì:
• Thử tiếp xúc với mèo trước khi mua
• Chọn giống ít gây dị ứng hơn: Sphynx, Siberian
• Hút bụi thường xuyên, tắm mèo định kỳ
• Không cho mèo vào phòng ngủ
Nhiều người dị ứng nhẹ vẫn nuôi mèo được sau khi thích nghi nhé! 🤧', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo bị cứng cổ là bị gì?', N'Cứng cổ ở mèo có thể do nhiều nguyên nhân: chấn thương cột sống cổ, viêm màng não, nhiễm trùng nặng. Đây là triệu chứng nghiêm trọng cần đưa đến bác sĩ thú y ngay nhé bạn. Không tự nắn bóp hay massage vùng cổ mèo vì có thể gây thương tổn thêm! 🏥', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'con mèo nhà tôi lười vãi', N'Haha bình thường bạn ơi! 😄 Mèo ngủ 12-16 tiếng mỗi ngày là bình thường. Khi thức thì bé rất tinh nghịch đó nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có bán Nhỏ gáy Frontline Plus phòng ký sinh không?', N'Có bạn nhé! Nhỏ gáy Frontline Plus phòng ký sinh giá 180.000đ. Diệt bọ chét ve rận hiệu quả 1 tháng không thấm nước. 🛍️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Tôi muốn mua mèo Bengal', N'Mèo Bengal tại shop giá 7-15 triệu bạn nhé! Lông đốm báo rất năng động và thông minh cần chơi nhiều. Bạn muốn biết thêm không? 😊', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay nhìn chằm chằm vào không khí là sao', N'Mèo nghe hoặc ngửi thấy điều gì đó bạn nhé! Thính giác và khứu giác mèo vượt xa người. Có thể côn trùng nhỏ, chuột trong tường, hoặc mùi từ ngoài. Không phải nhìn ma nhé! 😄', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mã giảm giá áp dụng thế nào', N'Nhập mã vào ô Mã giảm giá trong giỏ hàng trước khi thanh toán. Mỗi tài khoản dùng mỗi mã 1 lần nhé bạn! 🎟️', N'order', 1, GETUTCDATE(), GETUTCDATE()),
