(N'mèo nhà mình 3 tháng tuổi ăn được gì rồi', N'Mèo 3 tháng kết hợp 50% hạt kitten khô với 50% pate bạn nhé! Cho ăn 3-4 lần ngày. Đảm bảo luôn có nước sạch. Bé đang lớn nhanh lắm rồi nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo nằm lên laptop nóng có sao không', N'Mèo thích hơi ấm từ laptop nhưng không tốt cho cả hai bạn nhé! 😄 Lông mèo có thể lọt vào khe quạt gây hỏng máy. Mua heating pad mèo để bé có chỗ ấm riêng không ảnh hưởng công việc nhé! 💻', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có bán Nhà cây cho mèo cat tree 120cm không?', N'Có bạn nhé! Nhà cây cho mèo cat tree 120cm giá 850.000đ. Đáp ứng nhu cầu leo trèo cào móng và ngủ nghỉ giảm phá đồ trong nhà. 🛍️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop thanh toán bằng hình thức nào?', N'Shop hỗ trợ 2 hình thức:
• COD - thanh toán khi nhận hàng
• Chuyển khoản ngân hàng (có QR tự động)
Sau khi đặt hàng hệ thống gửi email xác nhận ngay cho bạn nhé! 💳', N'order', 1, GETUTCDATE(), GETUTCDATE()),
(N'rẻ hơn được không', N'Giá hiện tại đã là tốt nhất bạn nhé! Mèo tại shop có hồ sơ tiêm phòng rõ ràng và hỗ trợ sau mua 30 ngày. Bạn muốn tham khảo giống nào phù hợp ngân sách không? 😊', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Hạt Minino giá bao nhiêu?', N'Hạt Minino Yum vị hải sản 1.5kg tại shop giá 145.000đ bạn nhé. Minino là thương hiệu Việt Nam phổ biến, dinh dưỡng cân bằng, mèo thích ăn và giá phải chăng. Phù hợp mèo trưởng thành nhé! 🐟', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'hi', N'Hi bạn! 🐱 MeowBot đây! Mình có thể giúp gì cho bạn hôm nay? 😊', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'tết nguyên đán mèo có sao không', N'Mèo thường bị stress vào Tết do tiếng pháo và nhiều người lạ bạn nhé! Chuẩn bị phòng yên tĩnh riêng cho bé, đủ thức ăn nước khay cát sạch. Feliway giúp bé bình tĩnh hơn. Không ép bé tiếp xúc khách nhé! 🎆', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo con 1 tháng ăn gì', N'Mèo con 1 tháng vẫn cần bú mẹ hoặc sữa kitten bạn nhé! Tháng 4-5 tuần mới bắt đầu tập ăn pate siêu mềm pha loãng. Chưa nên cho ăn hạt khô nhé! 🍼', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có thể ở nhà một mình không', N'Mèo có thể ở nhà một mình trong ngày được bạn nhé! Chuẩn bị đủ thức ăn nước đồ chơi khay cát sạch. Vắng lâu hơn thì nhờ người ghé cho ăn nhé! 🏠', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo bị hắt hơi liên tục là bị gì?', N'Mèo hắt hơi 1-2 lần là bình thường do bụi hoặc mùi lạ. Hắt hơi liên tục kèm chảy nước mũi có thể do cảm cúp mèo herpesvirus calicivirus, dị ứng, hoặc có vật lạ trong mũi. Nếu kéo dài hơn 2 ngày hoặc có dịch mũi màu vàng xanh thì nên đưa đi khám nhé bạn! 🤧', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'shop có bảo hành sản phẩm không', N'Sản phẩm điện tử bảo hành 3-6 tháng tùy hãng. Phụ kiện vải đồ chơi được đổi nếu lỗi trong 3 ngày đầu bạn nhé! 🛡️', N'policy', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo cái và mèo đực tính cách khác nhau không', N'Có khác bạn nhé! Mèo đực thường xông xáo hơn, mèo cái thường cẩn thận hơn (trước khi triệt sản). Sau triệt sản sự khác biệt giảm nhiều. Tính cách từng cá thể quan trọng hơn giới tính nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'tiếng gừ gừ mèo có tần số gì', N'Tiếng gừ của mèo tần số 25-150 Hz bạn nhé! Tần số này được chứng minh thúc đẩy lành xương và cơ, giảm huyết áp. Có nghiên cứu cho rằng ngủ với mèo đang gừ tốt cho sức khỏe nhề! 💕', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị đỏ mắt phải làm sao', N'Lau nhẹ bằng bông gòn ẩm nước muối sinh lý. Vẫn đỏ sau 1-2 ngày hoặc có dịch vàng xanh thì cần đi khám và nhỏ thuốc theo chỉ định nhé bạn! 👁️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo bị đau bụng nhận biết thế nào?', N'Dấu hiệu mèo bị đau bụng: co rúm người, bụng căng cứng, không muốn bị sờ vào bụng, đi lại chậm chạp, không ăn, ngồi tư thế khom lưng bất thường. Đau bụng ở mèo có nhiều nguyên nhân từ nhẹ đến nghiêm trọng. Nếu kéo dài hơn vài giờ thì cần đưa đi khám ngay nhé bạn! 🏥', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có mèo Scottish Fold tai cụp không?', N'Có bạn nhé! Mèo Scottish Fold tai cụp tại shop giá 6-12 triệu. Tai cụp đặc trưng điềm tĩnh và quấn chủ. Bạn muốn biết thêm không? 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo tắm bằng nước lạnh được không', N'Không được, dùng nước ấm 38-39°C bạn nhé! 🛁', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Exotic Shorthair mèo Exotic có dễ chăm không', N'Mèo Exotic Shorthair mèo Exotic mặt bẹt như Ba Tư nhưng lông ngắn dễ chải hiền lành ít kêu. Giá 6-13 triệu. Nhìn chung đây là giống phù hợp cho người yêu mèo bạn nhé! Shop tư vấn cụ thể hơn nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo con hay ngủ cả ngày có sao không', N'Hoàn toàn bình thường bạn nhé! Mèo con ngủ 16-20h ngày, đây là thời gian cơ thể tiết hormone tăng trưởng. Chỉ lo nếu bé không ăn uống khi thức hoặc có dấu hiệu bệnh nhé! 😴', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Norwegian Forest Cat mèo rừng Na Uy có đặc điểm gì?', N'Mèo Norwegian Forest Cat mèo rừng Na Uy: lông dày dài chịu lạnh tốt cơ thể to khỏe thích leo trèo. Giá 10-20 triệu tại shop nhé bạn! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị nôn thường xuyên phải làm sao', N'Nôn 1-2 lần do búi lông bình thường. Nôn liên tục hơn 3 lần ngày có máu thì cần đi khám ngay bạn nhé! 🏥', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'shop có mèo ragdoll không', N'Có bạn nhé! Ragdoll tại shop giá 6-12 triệu. Đây là giống mèo siêu hiền, mềm xìu khi được bế, không cào cắn. Rất hợp gia đình có trẻ nhỏ nhé! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo già bị lú lẫn mất phương hướng là sao', N'Hội chứng rối loạn nhận thức ở mèo già (feline cognitive dysfunction) tương tự Alzheimer bạn nhé! Dấu hiệu: đi lơ ngơ, quên chỗ vệ sinh, kêu không lý do. Không chữa khỏi được nhưng có thể hỗ trợ bằng thuốc và môi trường ổn định nhé! 🏥', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo nào ít rụng lông nhất?', N'Các giống ít rụng lông:
• Sphynx: không có lông (ít nhất)
• Siamese: lông ngắn, ít rụng
• Devon Rex / Cornish Rex: lông xoăn ngắn, ít rụng
• Burmese: lông ngắn mịn
Mèo lông dài như Maine Coon, Ba Tư rụng lông nhiều hơn nhé! 🪮', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'hóa đơn VAT có xuất được không', N'Được bạn nhé! Chọn Xuất hóa đơn VAT khi đặt hàng và điền thông tin công ty. Hóa đơn gửi về email trong 3-5 ngày làm việc nhé! 🧾', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay liếm chủ là sao', N'Mèo liếm để thể hiện tình cảm, coi bạn là thành viên gia đình cần được chải lông. Dấu hiệu bé rất yêu quý bạn nhé! 😘', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Tôi muốn mua mèo Anh Lông Ngắn ALN golden', N'Mèo Anh Lông Ngắn ALN golden tại shop giá 8 triệu bạn nhé! Lông vàng rực rỡ cao cấp đang rất được săn đón. Bạn muốn biết thêm không? 😊', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'ragdoll giá mấy', N'Ragdoll tại shop giá 6-12 triệu tùy màu lông và giới tính bạn nhé! Hiện có nhiều bé đang chờ chủ. Bạn muốn tìm bé đực hay cái? 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có gây dị ứng không', N'Protein Fel d 1 trong nước bọt mèo gây dị ứng ở 10-15% người bạn nhé! Triệu chứng: hắt hơi, chảy nước mũi, ngứa mắt. Mèo đực chưa triệt sản gây dị ứng nhiều nhất. Có giống ít gây dị ứng hơn như Siberian và Balinese nhé! 🤧', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo cái động dục có dấu hiệu gì?', N'Mèo cái động dục thường từ 4-6 tháng tuổi: kêu gào to bất thường đặc biệt ban đêm, lăn lộn, cọ người vào đồ vật, nhấc đuôi lên khi được sờ vào lưng, không ăn hoặc ăn ít. Chu kỳ kéo dài 5-10 ngày lặp lại mỗi 2-3 tuần. Triệt sản là giải pháp tốt nhất! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo có thể học trick không?', N'Hoàn toàn có thể bạn nhé! Mèo học trick bằng clicker training hoặc thưởng snack. Các trick cơ bản: ngồi, nằm, lăn, đưa tay bắt, nhảy qua vòng. Mèo thông minh như Bengal, Abyssinian, Siamese học nhanh nhất. Buổi tập ngắn 5-10 phút nhé! 🎪', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'shop meow garden bán những gì', N'Meow Garden chuyên: 🐱 Mèo cảnh các giống ALN Ragdoll Bengal Maine Coon và nhiều giống khác, 🍖 Thức ăn hạt pate snack chuyên dụng, 🧺 Phụ kiện cát khay bát tháp mèo đồ chơi sữa tắm. Tất cả chính hãng chất lượng bạn nhé! ✨', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo phân biệt được ngày đêm không', N'Có bạn nhé! Mèo có đồng hồ sinh học hoạt động nhiều lúc chạng vạng sáng sớm. Ánh sáng ảnh hưởng chu kỳ này. Mèo trong nhà điều hòa đôi khi lệch chu kỳ hoạt động về đêm nhé! 🌙', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'có freeship không', N'Có! Đơn từ 500.000đ miễn phí ship nội thành HN và HCM nhé bạn! 🎉', N'shipping', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị đục thủy tinh thể là sao', N'Đục thủy tinh thể làm mắt mèo có màu trắng đục bạn nhé! Phổ biến ở mèo già và mèo tiểu đường. Ảnh hưởng thị lực nhưng mèo thích nghi tốt. Cần đi khám để đánh giá và điều trị nếu có thể nhé! 👁️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo cần bao nhiêu không gian để sống thoải mái', N'Không cần nhiều bằng chó bạn nhé! 1 mèo cần tối thiểu 1 phòng đủ đồ chơi và leo trèo. Quan trọng hơn là sự đa dạng theo chiều dọc (tháp mèo kệ cao) và thời gian chơi chất lượng với chủ nhé! 🏠', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo con mới sinh cần chăm sóc thế nào', N'Mèo con sơ sinh cần mẹ mèo bú sữa đầu colostrum trong 24h đầu bạn nhé! Nếu mẹ bỏ con thì cần sữa thay thế kitten milk replacer, ủ ấm 29-32°C, kích thích đi vệ sinh bằng bông ẩm nhé! 🍼', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo ăn mì gói có sao không', N'Không nên bạn nhé! Mì gói nhiều muối natri gây hại thận, gia vị độc hại với mèo. Thà cho bé nhịn còn hơn ăn mì gói nhé! ⚠️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo đực và mèo cái nuôi chung được không', N'Được bạn nhé, nhưng cần triệt sản cả hai trước khi nuôi chung. Chưa triệt sản thì sẽ sinh sản ngoài ý muốn và mèo đực hay hung hăng hơn với mèo cái chưa triệt sản nhé! ✂️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo có cần tắm nắng không?', N'Mèo rất thích nắng sáng nhé bạn! Nắng sáng (trước 9h) giúp mèo tổng hợp vitamin D, sưởi ấm và tốt cho tâm trạng. Tránh để mèo phơi nắng giữa trưa quá lâu vì dễ say nắng, đặc biệt mèo lông đen nhé! ☀️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay cắn móng tay người là sao', N'Mèo cắn móng tay vì mùi lạ hoặc muốn chơi bạn nhé! Không nguy hiểm nhưng có thể gây đau và nhiễm khuẩn nhẹ. Rửa tay trước khi chơi với bé và thay thế bằng đồ chơi nhé! 🧸', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Sinh nhật tôi có được giảm giá không?', N'Có chứ bạn ơi! Nếu bạn đăng ký ngày sinh nhật trong hồ sơ tài khoản, shop sẽ gửi mã giảm giá 10% vào đúng ngày sinh nhật, áp dụng cho toàn bộ sản phẩm trên website. Nhớ cập nhật thông tin trong tài khoản nhé! 🎂', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Abyssinian mèo Abys sống được bao lâu?', N'Mèo Abyssinian mèo Abys trung bình sống 12-16 năm nếu được chăm sóc tốt bạn nhé! Giá tại shop 6-12 triệu. Lông ngắn mướt hoạt động nhiều thông minh rất tò mò và năng động nhé! 🎂', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'meo hay non phai lam gi', N'Nôn 1-2 lần do búi lông bình thường bạn nhé! Nôn liên tục hơn 3 lần ngày có máu thì cần đi khám ngay nhé! 🏥', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị hói vùng tai là sao', N'Rụng lông vùng tai giữa mắt và tai thường do ve tai hoặc nấm da bạn nhé! Cần kiểm tra tai và dùng thuốc phù hợp. Cũng có thể là trạng thái bình thường ở một số giống không có gì đáng lo nhé! 👂', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo bị stress nhận biết thế nào?', N'Dấu hiệu mèo bị stress: ẩn náu nhiều hơn bình thường, bỏ ăn, đi vệ sinh sai chỗ, tự liếm lông quá mức gây hói, hung hăng hơn hoặc kêu nhiều bất thường. Nguyên nhân thường do: chuyển nhà, thêm thú cưng mới, tiếng ồn, mất người thân thiết nhé! 😿', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có phá đồ không', N'Ít hơn bạn lo! Mèo được chơi đủ thường rất ngoan. Cung cấp đồ chơi trụ cào móng tháp mèo để bé có nơi vui chơi hợp lệ nhé bạn! 🧸', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay nhìn vào tường là sao', N'Bé nghe hoặc ngửi thấy côn trùng chuột trong tường bạn nhé! Thính giác và khứu giác mèo nhạy hơn người rất nhiều nhé! 👂', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'dạy mèo không cào sofa thế nào', N'Đặt trụ cào móng cạnh sofa, khen khi bé dùng trụ, xịt nước chanh hoặc dán băng keo hai mặt lên chỗ hay cào, cắt móng 2 tuần một lần bạn nhé! Không phạt mà chuyển hướng sang trụ cào nhé! 🪵', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị đỏ mắt phải làm sao', N'Mắt mèo đỏ có thể do: viêm kết mạc nhiễm khuẩn, dị ứng, có vật lạ vào mắt, hoặc herpesvirus mèo. Lau nhẹ bằng bông gòn ẩm nước muối sinh lý từ góc trong ra ngoài. Nếu mắt tiếp tục đỏ sau 1-2 ngày hoặc có dịch vàng xanh thì cần đi khám và dùng thuốc nhỏ mắt theo chỉ định nhé! 👁️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo cái động dục dấu hiệu gì', N'Kêu gào to bất thường nhất là ban đêm, lăn lộn, cọ người vào đồ vật, nhấc đuôi khi được sờ vào lưng, ít ăn. Triệt sản là giải pháp tốt nhất nhé bạn! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Anh lông ngắn bicolor là màu gì?', N'ALN Bicolor là lông chia hai mảng màu rõ ràng bạn nhé - thường là trắng kết hợp với xám, đen hoặc vàng, phân chia rất đối xứng và đẹp mắt. Khuôn mặt thường có mũi và cằm trắng rất ngây thơ. Hiện shop có bé bicolor đực 7 tháng giá 6.5 triệu! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Tôi muốn mua mèo Mèo ta mướp', N'Mèo Mèo ta mướp tại shop giá 500k-2 triệu bạn nhé! Khỏe mạnh thích nghi tốt ít bệnh phù hợp người mới nuôi. Bạn muốn biết thêm không? 😊', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có mèo Maine Coon không?', N'Có bạn nhé! Mèo Maine Coon tại shop giá 8-18 triệu. Giống to nhất thế giới rất thông minh và thân thiện. Bạn muốn biết thêm không? 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Abyssinian mèo Abys nặng bao nhiêu kg', N'Mèo Abyssinian mèo Abys trưởng thành thường 3-6kg bạn nhé! Lông ngắn mướt hoạt động nhiều thông minh rất tò mò và năng động. Giá 6-12 triệu tại shop nhé! ⚖️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có cần tắm nắng không', N'Mèo rất thích tắm nắng và nó tốt cho sức khỏe bạn nhé! Vitamin D tổng hợp qua lông và da, nhiệt độ ấm giúp xương khớp. Đảm bảo mèo không bị kẹt ngoài nắng quá lâu có thể say nắng nhé! ☀️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo mua về bị ốm ngay', N'Xin lỗi bạn rất nhiều nhé! 🙏 Đây đúng trong chính sách hỗ trợ 72h của shop. Bạn đưa bé đi khám và gửi hóa đơn cho shop, shop hoàn 100% chi phí nhé!', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Munchkin chân ngắn nuôi có khó không?', N'Mèo Munchkin chân ngắn chân ngắn đặc trưng vui vẻ nghịch ngợm. Giá 5-9 triệu. Về độ khó chăm sóc hãy hỏi thêm mình tư vấn cụ thể nhé bạn! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Siamese mèo Xiêm có đặc điểm gì?', N'Mèo Siamese mèo Xiêm: mắt xanh sắc nét hay kêu giao tiếp tình cảm. Giá 4-8 triệu tại shop nhé bạn! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị điện giật phải làm sao', N'Ngắt điện trước, KHÔNG chạm tay vào mèo khi còn nguồn điện bạn nhé! Dùng vật không dẫn điện đẩy mèo khỏi nguồn. Đưa đến bệnh viện thú y ngay dù mèo tỉnh lại nhanh nhé! 🚨', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'có thể khám thú y online không', N'Một số phòng khám có dịch vụ tư vấn online bạn nhé! Phù hợp cho câu hỏi cơ bản theo dõi sau điều trị. Vấn đề nghiêm trọng cần khám trực tiếp để thăm khám và xét nghiệm nhé! 📱', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo không có giấy tờ có đáng mua không', N'Mèo không giấy tờ thường giá thấp hơn bạn nhé! Nhưng cần kiểm tra sức khỏe kỹ và tiêm phòng đầy đủ. Mèo cảnh cao cấp thuần chủng nên có giấy chứng nhận để đảm bảo nguồn gốc nhé! 📋', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Sphynx không lông giá bao nhiêu?', N'Mèo Sphynx không lông tại shop giá từ 8-15 triệu bạn nhé. Sphynx rất thân thiện, thích được ôm ấp để giữ ấm, không lo dị ứng lông mèo. Cần tắm thường xuyên hơn vì da tiết nhiều dầu nhé! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N't muốn nuôi mèo lần đầu nên mua giống gì', N'Chào mừng bạn đến với thế giới nuôi mèo! 🐱 Cho người lần đầu nuôi mèo shop gợi ý:
• Mèo ta mướp: rẻ, khỏe, ít bệnh - lý tưởng nhất
• Mèo Anh Lông Ngắn: hiền, không đòi hỏi nhiều
• Mèo Ragdoll: cực hiền, không cào cắn
Tránh giống khó chăm như Sphynx, Maine Coon trước mắt nhé! 😊', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay đứng ở cửa ra vào chờ chủ là sao', N'Mèo nghe và ngửi thấy chủ sắp về từ xa bạn nhé! Nghiên cứu cho thấy mèo học lịch về nhà của chủ. Đây là cách bé thể hiện tình cảm chờ đợi. Rất đáng yêu và chứng minh mèo quan tâm chủ nhé! 🥰', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo già hay kêu đêm là sao', N'Mèo già kêu đêm thường do: đau, mất phương hướng do lú lẫn, tăng huyết áp, cường giáp, hoặc đơn giản là cô đơn bạn nhé! Cần đi khám để loại trừ bệnh lý trước khi xử lý hành vi nhé! 🌙', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'tiết trời hanh khô ảnh hưởng đến mèo thế nào', N'Không khí khô có thể gây kích ứng đường hô hấp và làm lông da khô bạn nhé! Máy tạo ẩm trong phòng rất hữu ích. Tăng lượng wet food bổ sung độ ẩm. Omega 3 cải thiện tình trạng da lông khô nhé! 💨', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo rẻ nhất bao nhiêu', N'Mèo rẻ nhất là mèo mướp ta từ 500k-2 triệu. Nếu muốn giống ngoại giá thấp thì ALN xám xanh 4.5 triệu là tốt nhất bạn nhé! 💸', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Anh Lông Ngắn ALN bicolor có dễ chăm không', N'Mèo Anh Lông Ngắn ALN bicolor lông chia 2 màu đối xứng rất đẹp tính cách điềm tĩnh. Giá 6.5 triệu. Nhìn chung đây là giống dễ chăm bạn nhé! Liên hệ shop để tư vấn cụ thể nhé! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'nuôi mèo có tốn nhiều không', N'Khoảng 450-900k mỗi tháng thôi bạn nhé! Gồm thức ăn, cát và thú y định kỳ. Rẻ hơn cà phê hàng ngày mà có người bạn đồng hành 15-18 năm nhé! ☕', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo bị chảy dãi là bị gì?', N'Mèo chảy dãi khi: đang được vuốt ve thoải mái (bình thường), buồn nôn, bệnh răng miệng (viêm lợi, sâu răng), ăn phải thứ đắng hoặc độc, hoặc say xe. Nếu chảy dãi nhiều bất thường kèm mùi hôi miệng thì nên kiểm tra răng miệng tại bác sĩ thú y nhé! 💧', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'chải lông cho mèo bao lâu một lần', N'Mèo lông ngắn: 1-2 lần tuần. Mèo lông dài như Ba Tư Maine Coon: hàng ngày để tránh rối bết bạn nhé! Khi lột xác theo mùa cần chải thêm. Chải lông còn tạo bond với bé nhé! 🪮', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'tôi lo mèo bệnh sau khi mua', N'Bạn yên tâm nhé! Tất cả mèo tại shop được kiểm tra sức khỏe đầy đủ trước khi bán. Nếu bé bệnh trong 72h đầu shop hỗ trợ 100% chi phí khám và điều trị. Hỗ trợ tư vấn 30 ngày miễn phí! 💚', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo con nên ngủ ở đâu', N'Mèo con nên có ổ riêng ấm áp và kín đáo bạn nhé. Những ngày đầu bé mới về có thể để ổ trong phòng bạn ngủ để bé yên tâm hơn. Chuẩn bị: chăn hoặc đệm nhỏ mềm, hộp carton có lót chăn, tránh chỗ có gió lùa và ẩm ướt. Khi bé quen hơn thì dần cho bé ngủ ổ riêng nhé! 🛏️', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị rụng lông thành mảng tròn là sao', N'Rụng lông tròn có thể do nấm da ringworm bạn nhé! Rất dễ lây sang người và mèo khác. Cần đi khám, cách ly bé, dùng thuốc kháng nấm theo chỉ định. Không tự mua thuốc ngoài nhé! 🏥', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'bao lâu thì mèo mới quen nhà', N'Hầu hết mèo quen cơ bản trong 1-2 tuần bạn nhé! Quen hoàn toàn coi đây là nhà thường mất 1-3 tháng. Mèo con quen nhanh hơn mèo trưởng thành. Kiên nhẫn là chìa khóa nhé! 🏠', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay đi vệ sinh ngoài khay', N'Hay xảy ra vì: khay bẩn, vị trí không phù hợp, cát không thích, hoặc stress bạn nhé! Dọn khay ngay sau mỗi lần dùng, thử đổi loại cát khác, đặt thêm 1 khay nữa xem sao nhé! 🚽', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo có nhận ra chủ không?', N'Có bạn ơi! Mèo nhận ra chủ qua giọng nói, mùi cơ thể và khuôn mặt. Mèo thường thể hiện tình cảm bằng cách: đầu húc vào người, chớp mắt chậm (nụ hôn mèo), nằm lên đùi, mang đồ vật đến tặng, hoặc kêu gừ gừ khi được vuốt ve nhé! 🥰', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'minino có tốt không', N'Minino thương hiệu Việt Nam uy tín và phổ biến. Dinh dưỡng cân bằng giá phải chăng mèo thích ăn bạn nhé. Phù hợp làm thức ăn hàng ngày! 🌾', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Anh Lông Ngắn ALN bicolor tính cách thế nào?', N'Mèo Anh Lông Ngắn ALN bicolor lông chia 2 màu đối xứng rất đẹp tính cách điềm tĩnh. Giá 6.5 triệu rất phù hợp nhé bạn! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo ăn nhiều mà vẫn gầy là sao', N'Ăn nhiều mà gầy thường do: ký sinh trùng đường ruột, cường giáp ở mèo già, tiểu đường, hoặc bệnh ruột bạn nhé! Cần đi khám và xét nghiệm để tìm nguyên nhân. Không tự tăng lượng ăn mà không biết nguyên nhân nhé! 🏥', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay ngứa gãi không ngừng là sao', N'Ngứa liên tục thường do bọ chét (ngứa vùng lưng đuôi), ghẻ ngứa, dị ứng hoặc nhiễm nấm bạn nhé! Kiểm tra lông kỹ tìm bọ chét, nếu không thấy thì cần đi khám da liễu thú y nhé! 🦟', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có thể huấn luyện bằng clicker không', N'Rất hiệu quả bạn nhé! Click ngay khi bé làm đúng rồi thưởng trong 1-2 giây. Mèo học nhanh với âm thanh cụ thể hơn lời nói. Clicker training tốt hơn la mắng rất nhiều nhé! 🎯', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Cát thủy tinh giá bao nhiêu?', N'Cát thủy tinh khử mùi tại shop giá 150.000đ/5L bạn nhé. Cát thủy tinh khử mùi tốt nhất trong các loại cát, thay ít thường xuyên hơn (2-4 tuần/lần), không vón cục nhưng cần thay toàn bộ định kỳ nhé! 💎', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Cát vệ sinh nào tốt nhất?', N'Mỗi loại cát có ưu điểm riêng:
• Cát bentonite: vón tốt, rẻ nhưng nhiều bụi
• Cát đậu nành tofu: an toàn, ít bụi, thân thiện môi trường - shop giá 120k/6L
• Cát thủy tinh: khử mùi tốt nhất, thay ít hơn - shop giá 150k/5L
Shop khuyên dùng cát đậu nành cho mèo con và cát thủy tinh cho nhà nhiều mèo nhé! 🏆', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay gãi tai là bị gì', N'Mèo hay gãi tai thường do: ghẻ tai (thấy bụi đen trong tai), nhiễm nấm men, hoặc nhiễm khuẩn tai. Kiểm tra bằng cách nhìn vào trong tai bé. Nếu thấy bụi đen nâu thì khả năng cao là ghẻ tai. Dùng dung dịch vệ sinh tai chuyên dụng và đưa đi khám để được chỉ định thuốc đúng nhé bạn! 👂', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo 3 tháng ăn gì', N'Mèo 3 tháng tuổi đang trong giai đoạn phát triển nhanh bạn nhé! Kết hợp hạt kitten khô + pate mềm theo tỷ lệ 50-50. Cho ăn 3-4 lần ngày với lượng theo bao bì hướng dẫn. Đảm bảo luôn có nước sạch. Thức ăn chuyên dụng cho kitten đầy đủ dinh dưỡng hơn thức ăn người nhé! 🐱', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị liếm lông đến rụng là sao', N'Liếm quá mức (overgrooming) đến rụng lông thành vùng thường do: stress, dị ứng, đau hoặc ký sinh trùng bạn nhé! Cần tìm nguyên nhân gốc thay vì chỉ ngăn bé liếm. Đôi khi cần thuốc lo âu nhé! 🏥', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo lông ngắn hay lông dài dễ chăm hơn', N'Lông ngắn dễ chăm hơn bạn nhé! Chải 1-2 lần tuần, không bị rối bết. Lông dài cần chải hàng ngày tránh rối bết đặc biệt Ba Tư Maine Coon. Bù lại lông dài đẹp và ấm hơn nhé! 🪮', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hoang có nguy hiểm không', N'Mèo hoang thường sợ người và tránh xa bạn nhé! Nguy hiểm chủ yếu khi bị dồn vào góc tường mới cào cắn. Rửa sạch ngay nếu bị cào, tiêm phòng dại nếu lo ngại. Nuôi từ nhỏ thì nguy hiểm rất ít nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có ăn được phô mai không', N'Một miếng nhỏ phô mai không gây hại ngay nhưng mèo không tiêu hóa tốt lactose bạn nhé! Cho ăn thường xuyên gây tiêu chảy. Snack mèo chuyên dụng tốt hơn nhé! 🧀', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay ợ sau khi ăn là sao', N'Ợ nhẹ đôi khi sau ăn bình thường bạn nhé! Thường do ăn quá nhanh. Thử dùng bát ăn chậm slow feeder hoặc chia nhỏ bữa ăn thành nhiều lần hơn. Ợ thường xuyên kèm nôn thì đi khám nhé! 🍽️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay nháy mắt nhanh là sao', N'Nháy mắt nhanh liên tục có thể do: bụi vào mắt, dị ứng, hoặc nhiễm trùng mắt bạn nhé! Một lần chớp nháy bình thường. Nháy không ngừng kèm chảy nước mắt nhiều thì cần kiểm tra nhé! 👁️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Exotic Shorthair mèo Exotic tính cách thế nào?', N'Mèo Exotic Shorthair mèo Exotic mặt bẹt như Ba Tư nhưng lông ngắn dễ chải hiền lành ít kêu. Giá 6-13 triệu rất phù hợp nhé bạn! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Anh Lông Dài ALD trắng nuôi có khó không?', N'Mèo Anh Lông Dài ALD trắng lông xù bồng bềnh cần chải hàng ngày. Giá 5 triệu. Về độ khó chăm sóc hãy hỏi thêm mình tư vấn cụ thể nhé bạn! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị ốm có tiêm vaccine được không', N'Không nên bạn nhé! Tiêm vaccine khi mèo đang bệnh có thể làm bệnh nặng hơn và vaccine không hiệu quả. Chờ bé khỏe hoàn toàn 1-2 tuần sau đó tiêm nhé! 💉', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'shop meow garden đẹp không', N'Meow Garden được thiết kế rất đẹp và thân thiện bạn nhé! Website có giao diện hồng pastel dễ thương, dễ tìm sản phẩm và mèo cảnh. Bạn có thể xem ảnh các bé mèo rõ nét, thông tin đầy đủ và đặt hàng dễ dàng. Ghé website hoặc showroom trực tiếp để trải nghiệm nhé! 🌸', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'meo con 2 thang an gi vay', N'Mèo con 2 tháng ăn pate mềm 3-4 lần ngày bạn nhé! Có thể thêm hạt kitten ngâm mềm. Tránh sữa bò và thức ăn người nhé! 🍼', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'shop bảo mật thông tin cá nhân không', N'Có bạn nhé! Meow Garden cam kết bảo mật thông tin khách hàng. Dữ liệu chỉ dùng để xử lý đơn hàng và liên lạc khi cần. Không chia sẻ cho bên thứ ba nhé! 🔒', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo có ăn được sữa bò không?', N'Không nên bạn ơi! Đa số mèo trưởng thành bị bất dung nạp lactose trong sữa bò, có thể gây tiêu chảy. Nếu muốn cho mèo uống sữa, hãy dùng sữa dành riêng cho mèo (không có lactose) bán tại shop nhé! 🥛', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo có ăn rau không?', N'Mèo là động vật ăn thịt hoàn toàn, không cần rau củ trong khẩu phần bạn nhé. Tuy nhiên một số mèo thích gặm cỏ mèo để hỗ trợ tiêu hóa và nôn búi lông. Không cần bổ sung rau vào khẩu phần thường xuyên nhé! 🥕', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'shop giao hàng không', N'Có bạn nhé! Shop giao hàng toàn quốc qua GHN GHTK và J&T. Nội thành HN HCM giao 1-2 ngày, tỉnh xa 3-5 ngày làm việc nhé! 🚚', N'shipping', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay nằm trên người là sao', N'Bé thể hiện tình cảm và tin tưởng bạn nhé! Cơ thể người ấm, mèo cảm thấy an toàn. Đây là cách bé coi bạn là thành viên gia đình đó! 🥰', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Khay vệ sinh mèo giá bao nhiêu?', N'Khay vệ sinh thành cao chống văng tại shop giá 180.000đ bạn nhé. Thành cao giúp tránh cát bắn ra ngoài khi mèo bới, dễ vệ sinh. Shop cũng có khay có nắp đậy kín hơn nếu bạn cần nhé! 🚽', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Sphynx không lông nuôi có khó không?', N'Mèo Sphynx không lông không lông thích ôm ấp giữ ấm ít gây dị ứng. Giá 8-15 triệu. Về độ khó chăm sóc hãy hỏi thêm mình tư vấn cụ thể nhé bạn! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Norwegian Forest Cat mèo rừng Na Uy ăn hạt gì tốt', N'Mèo Norwegian Forest Cat mèo rừng Na Uy nên ăn hạt chất lượng phù hợp tuổi bạn nhé! Royal Canin hoặc Minino đều tốt. Giá bé 10-20 triệu. Shop tư vấn thêm nhé! 🌾', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'tại sao mèo thích hộp carton', N'Mèo thích không gian nhỏ kín vì cảm giác an toàn như hang ổ trong tự nhiên bạn nhé! Còn kiểm soát được ai tiếp cận từ một hướng. Nhiệt độ trong hộp cũng giữ ấm tốt nhé! 📦', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Munchkin chân ngắn có hợp với trẻ em không?', N'Mèo Munchkin chân ngắn chân ngắn đặc trưng vui vẻ nghịch ngợm. Giá 5-9 triệu. Để biết có hợp trẻ em không bạn cho mình biết bé mấy tuổi để tư vấn phù hợp nhé! 👶', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo con mấy tháng thì tiêm vaccine?', N'Lịch tiêm chuẩn cho mèo con:
• 8 tuần tuổi: Vaccine 3 bệnh mũi 1
• 12 tuần: Vaccine 3 bệnh mũi 2 + vaccine dại mũi 1
• 16 tuần: Vaccine 3 bệnh mũi 3 + vaccine dại mũi 2
• Hàng năm tiêm nhắc lại nhé bạn! 💉', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'ALN xám xanh giá bao nhiêu?', N'Mèo Anh Lông Ngắn xám xanh tại shop giá 4.5 triệu bạn nhé. Đây là màu cổ điển và phổ biến nhất của ALN, bộ lông xám ánh xanh đặc trưng rất sang. Bé đang 1 tháng tuổi, đực, rất hiếu động và đáng yêu! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Abyssinian mèo Abys tính cách thế nào?', N'Mèo Abyssinian mèo Abys lông ngắn mướt hoạt động nhiều thông minh rất tò mò và năng động. Giá 6-12 triệu rất phù hợp nhé bạn! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bệnh thận ăn gì', N'Mèo bệnh thận cần chế độ ăn ít phosphorus ít sodium giảm protein bạn nhé! Thức ăn prescription cho thận như Royal Canin Renal hoặc Hill''s k/d. Không tự thay đổi chế độ ăn mà cần theo bác sĩ nhé! 🏥', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay vẫy đuôi khi ngủ là sao', N'Vẫy đuôi khi ngủ là bé đang mơ bạn nhé! Trong giai đoạn ngủ REM mèo tái hiện các hoạt động ban ngày như săn mồi. Giống hệt người mơ giật tay chân. Hoàn toàn bình thường nhé! 💤', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo anh lông ngắn có tốt không', N'ALN là giống mèo quốc dân rất phổ biến ở Việt Nam bạn nhé! Mặt nọng béo tròn cực cute, tính cách hiền lành điềm tĩnh, ít kêu, không đòi hỏi nhiều. Rất phù hợp người mới nuôi nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo nên ăn hạt hay pate?', N'Tốt nhất kết hợp cả hai bạn ơi! 70% hạt khô + 30% pate là lý tưởng. Hạt khô giúp làm sạch răng và dinh dưỡng cân bằng, pate bổ sung độ ẩm dễ ăn hơn. Mèo con dưới 3 tháng nên ưu tiên pate mềm nhé! 🍖', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có mèo Anh Lông Ngắn ALN bicolor không?', N'Có bạn nhé! Mèo Anh Lông Ngắn ALN bicolor tại shop giá 6.5 triệu. Lông chia 2 màu đối xứng rất đẹp tính cách điềm tĩnh. Bạn muốn biết thêm không? 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo ba tư có khó chăm không', N'Ba Tư cần chải lông hàng ngày tránh rối bết và lau mắt thường xuyên vì hay chảy nước mắt do cấu trúc mặt bạn nhé. Nếu bạn có thời gian chăm sóc hàng ngày thì Ba Tư rất xứng đáng nhé! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có bán Snack thưởng Churu salmon 14g không?', N'Có bạn nhé! Snack thưởng Churu salmon 14g giá 15.000đ. Mèo cực thích dạng sệt giàu độ ẩm tốt cho thận dùng làm phần thưởng. 🛍️', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có bán Sữa tắm SOS chuyên dụng 530ml không?', N'Có bạn nhé! Sữa tắm SOS chuyên dụng 530ml giá 120.000đ. Dịu nhẹ an toàn dùng được từ 3 tháng tuổi. 🛍️', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay thở bằng miệng là sao', N'Mèo bình thường không thở bằng miệng bạn nhé, khác với chó. Mèo thở miệng là dấu hiệu bất thường cần chú ý: có thể do quá nóng và mệt sau khi chạy nhảy nhiều (hết trong vài phút là bình thường), hoặc nghiêm trọng hơn là bệnh tim hoặc phổi. Nếu thở miệng kéo dài hơn 5 phút khi nghỉ ngơi thì cần đưa đi khám ngay nhé! 🏥', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo có cần vitamin không?', N'Nếu mèo đang ăn thức ăn công nghiệp chất lượng tốt thì thường không cần bổ sung vitamin thêm bạn nhé vì đã cân bằng đủ dinh dưỡng. Chỉ cần bổ sung theo chỉ định bác sĩ khi mèo ốm, mang thai, già yếu hoặc biếng ăn. Tự bổ sung vitamin quá nhiều có thể gây ngộ độc! 💊', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Snack thưởng Churu salmon 14g giá bao nhiêu?', N'Snack thưởng Churu salmon 14g tại shop giá 15.000đ bạn nhé! Mèo cực thích dạng sệt giàu độ ẩm tốt cho thận dùng làm phần thưởng. 🛍️', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'meo bi tieu chay phai lam sao', N'Nhịn ăn 6-8h rồi cho ăn gà luộc nhạt bạn nhé! Đảm bảo uống đủ nước. Tiêu chảy có máu hoặc kéo dài hơn 24h thì đi khám ngay nhé! 🏥', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo bị nôn phải làm sao?', N'Mèo nôn 1-2 lần do búi lông hoặc ăn quá nhanh là bình thường. Cần đi khám ngay nếu:
• Nôn liên tục hơn 3 lần/ngày
• Nôn có máu hoặc dịch vàng xanh
• Kèm lờ đờ bỏ ăn hơn 24h
Shop có gel tiêu búi lông giúp phòng ngừa nhé! 🏥', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo có hợp với người hay đi công tác không?', N'Mèo hợp hơn chó cho người hay đi vắng vì mèo độc lập hơn. Có thể để thức ăn tự động 1-2 ngày với máy cho ăn tự động và đủ nước. Đi vắng lâu hơn thì nhờ người thân ghé cho ăn 1 lần ngày là đủ. Nuôi 2 mèo giúp bé đỡ cô đơn khi chủ vắng nhé! ✈️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo ăn hành có sao không', N'Rất nguy hiểm bạn ơi! Hành và tỏi phá hủy hồng cầu mèo gây thiếu máu. Nếu mèo lỡ ăn hành thì đưa đi khám ngay nhé! ⚠️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Bengal có hợp với trẻ em không?', N'Mèo Bengal lông đốm báo rất năng động và thông minh cần chơi nhiều. Giá 7-15 triệu. Để biết có hợp trẻ em không bạn cho mình biết bé mấy tuổi để tư vấn phù hợp nhé! 👶', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'dạy mèo đến khi gọi tên thế nào', N'Gọi tên rồi thưởng ngay khi bé đến bạn nhé! Bắt đầu trong phòng nhỏ, dần dần gọi từ xa hơn. Chỉ gọi khi có thưởng, không bao giờ gọi bé đến rồi làm điều bé không thích như tắm nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'hạt mèo loại nào ngon', N'Mèo thích: Churu và Ciao snack thưởng, Royal Canin hạt cao cấp, Minino hạt Việt giá hợp lý bạn nhé! Thử vài loại để biết bé nhà bạn thích loại nào nhất nhé! 🌾', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay leo lên bàn phím là sao', N'Mèo leo lên bàn phím vì muốn được chú ý khi bạn đang làm việc, máy tính ấm bé thích, hoặc muốn nằm giữa bạn và màn hình. Giải pháp: chơi với bé trước khi làm việc để bé được thỏa mãn nhé! 💻', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo mang thai bao lâu thì đẻ?', N'Mèo mang thai khoảng 63-67 ngày (khoảng 9 tuần) bạn nhé. Dấu hiệu mang thai: bụng to dần sau 3-4 tuần, núm vú hồng và to hơn, ăn nhiều hơn, tìm nơi yên tĩnh làm ổ. Cần bổ sung dinh dưỡng tốt hơn và đưa đi khám để theo dõi thai kỳ nhé! 🐣', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Lược chải lông mèo Furminator giá bao nhiêu?', N'Lược chải lông mèo Furminator tại shop giá 250.000đ bạn nhé! Loại bỏ lông chết tận gốc giảm rụng lông đến 90%. 🛍️', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'bengal có thể nuôi trong nhà nhỏ không', N'Bengal cần không gian vận động và kích thích tinh thần nhiều bạn nhé! Căn hộ nhỏ vẫn được nếu có đủ đồ chơi tháp mèo và thời gian chơi 30-45 phút ngày. Thiếu kích thích Bengal sẽ phá đồ nhé! 🐆', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo 3 triệu có không', N'Ở mức 3 triệu bạn có thể mua mèo ta cao cấp hoặc mèo lai F1 bạn nhé. Mèo giống ngoại thuần chủng thường bắt đầu từ 4.5 triệu. Liên hệ shop để xem bé hiện có nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'persian ba tư chảy nước mắt nhiều là sao', N'Mèo Ba Tư có cấu trúc mặt bẹt khiến ống lệ bị hẹp tự nhiên gây chảy nước mắt nhiều bạn nhé! Cần lau mắt hàng ngày bằng bông gòn ẩm. Không phải bệnh mà là đặc trưng giống nhé! 👁️', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay mang đồ vật cho chủ là sao', N'Mèo đang chia sẻ chiến lợi phẩm với bạn - thành viên gia đình thân thiết! Hãy khen ngợi bé để củng cố hành vi tình cảm này nhé! 🎁', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Maine Coon sống được bao lâu?', N'Mèo Maine Coon trung bình sống 12-16 năm nếu được chăm sóc tốt bạn nhé! Giá tại shop 8-18 triệu. Giống to nhất thế giới rất thông minh và thân thiện nhé! 🎂', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Anh Lông Ngắn ALN xám xanh có hợp với trẻ em không?', N'Mèo Anh Lông Ngắn ALN xám xanh hiền lành quấn chủ màu xám xanh đặc trưng. Giá 4.5 triệu. Để biết có hợp trẻ em không bạn cho mình biết bé mấy tuổi để tư vấn phù hợp nhé! 👶', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'một mèo hay hai mèo nuôi vui hơn', N'Hai mèo thường vui hơn bạn nhé! Hai bé chơi với nhau ít phá đồ hơn, ít cô đơn khi chủ vắng, phát triển xã hội tốt hơn. Chi phí tăng gần gấp đôi nhưng hạnh phúc tăng gấp nhiều lần nhé! 🐱🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có thể học tên bao lâu', N'Mèo học tên trong 1-2 tuần nếu gọi nhất quán bạn nhé! Gọi tên khi cho ăn, khi chơi, khi khen ngợi. Tên ngắn 1-2 âm tiết bé học nhanh hơn. Không gọi tên khi làm điều bé không thích nhé! 🗣️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị rụng râu có sao không', N'Râu mèo (vibrissae) rất quan trọng bạn nhé - giúp mèo định hướng và cảm nhận không gian xung quanh. Râu rụng tự nhiên đôi khi là bình thường. Tuyệt đối không cắt râu mèo vì sẽ làm bé mất phương hướng và rất stressed. Nếu râu rụng nhiều bất thường thì có thể do stress hoặc bệnh, cần đưa đi khám nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo tam thể có không', N'Mèo tam thể (3 màu trắng-đen-vàng/cam) là mèo đặc biệt bạn nhé! Theo di truyền học hầu hết mèo tam thể đều là mèo cái (99%). Mèo tam thể đực cực hiếm và thường vô sinh. Shop có thể có mèo tam thể tùy thời điểm. Liên hệ shop để hỏi về các bé hiện có nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Anh Lông Ngắn ALN golden tính cách thế nào?', N'Mèo Anh Lông Ngắn ALN golden lông vàng rực rỡ cao cấp đang rất được săn đón. Giá 8 triệu rất phù hợp nhé bạn! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'birman mèo thánh có đặc điểm nổi bật gì', N'Birman đặc biệt có 4 bàn chân trắng như đi tất bạn nhé! Lông semi-long ít rối, mặt hiền từ, mắt xanh sâu. Tính cách nhẹ nhàng không hung hăng. Giá 5-10 triệu tại shop nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Royal Canin có tốt không?', N'Royal Canin là thương hiệu thức ăn mèo cao cấp và uy tín nhất thế giới bạn nhé. Được bác sĩ thú y khuyến nghị rộng rãi, có công thức riêng cho từng giống mèo ALN, Ba Tư, Ragdoll và từng giai đoạn sức khỏe. Giá cao hơn nhưng chất lượng dinh dưỡng rất tốt! ⭐', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Mèo ta mướp có dễ chăm không', N'Mèo Mèo ta mướp khỏe mạnh thích nghi tốt ít bệnh phù hợp người mới nuôi. Giá 500k-2 triệu. Nhìn chung đây là giống cần chú ý một chút bạn nhé! Liên hệ shop để tư vấn cụ thể nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có thể ăn cơm không', N'Cơm trắng không gia vị một ít an toàn nhưng không có dinh dưỡng cho mèo bạn nhé! Mèo là động vật ăn thịt nghiêm ngặt cần protein không cần tinh bột nhé! 🍚', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'shop có nhận đặt hàng trước không', N'Có bạn nhé! Đặt cọc 30-50% để giữ bé hoặc sản phẩm đang hết hàng. Thông thường hàng về 3-7 ngày làm việc. Liên hệ nhân viên để biết thêm chi tiết nhé! 📦', N'order', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay đưa bàn chân vỗ vỗ mặt chủ là sao', N'Đây là cách mèo thu hút sự chú ý nhẹ nhàng bạn nhé! 😄 Bé muốn bạn thức dậy cho ăn hoặc chơi. Nếu không thích thì đừng phản ứng, bé sẽ học rằng cách này không hiệu quả nhé! 🐾', N'general', 1, GETUTCDATE(), GETUTCDATE()),
