(N'Tôi muốn mua Đồ chơi cần câu lông vũ', N'Bạn chọn đúng rồi! Đồ chơi cần câu lông vũ kích thích bản năng săn mồi giúp mèo vận động và giải trí. Giá 45.000đ tại shop. Đặt hàng trên website nhé! 🛒', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'đặt hàng qua điện thoại được không', N'Được bạn nhé! Liên hệ qua fanpage Zalo hoặc hotline để đặt hàng. Nhân viên hỗ trợ chọn hàng tư vấn và xác nhận đơn qua điện thoại nhé! 📞', N'order', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo bao nhiêu tháng thì về nhà được?', N'Mèo con nên được về nhà mới khi đủ 8-12 tuần tuổi bạn nhé. Trước 8 tuần bé còn cần học kỹ năng xã hội từ mẹ và anh chị em. Tất cả mèo tại shop đều đủ tuổi và đã tiêm phòng trước khi bàn giao nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo mới về mấy ngày thì chơi được', N'Đa số mèo bắt đầu tự ra khám phá sau 3-5 ngày bạn nhé! Chơi nhẹ nhàng với cần câu từ xa không chạm thẳng vào bé. Đừng ép buộc, để bé chủ động tiếp cận nhé! 🧸', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Nhỏ gáy Frontline Plus phòng ký sinh giá bao nhiêu?', N'Nhỏ gáy Frontline Plus phòng ký sinh tại shop giá 180.000đ bạn nhé! Diệt bọ chét ve rận hiệu quả 1 tháng không thấm nước. 🛍️', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'bye meowbot', N'Tạm biệt bạn! 🐱 Meow Garden và MeowBot luôn ở đây khi bạn cần nhé. Chúc bạn một ngày thật vui cùng bé mèo nhà mình! 🐾✨', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'hủy đơn hàng được không', N'Được khi đơn còn trạng thái Chờ xác nhận. Khi đã Đang giao thì không hủy được. Liên hệ shop sớm nhất nhé bạn! 📦', N'policy', 1, GETUTCDATE(), GETUTCDATE()),
(N'cúp điện mèo có sao không', N'Mèo chịu đựng tốt hơn người khi mất điện bạn nhé! Tuy nhiên vào mùa hè nóng nực cần đảm bảo: đủ nước uống sạch, thông gió tự nhiên, không để mèo trong phòng kín nắng. Nhiệt độ trên 35°C kéo dài có thể gây sốc nhiệt cho mèo. Chuẩn bị đá hoặc khăn mát nếu mùa hè cúp điện lâu nhé bạn! ❄️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo nào ít rụng lông nhất', N'Ít rụng lông nhất: Sphynx hầu như không rụng, Rex (Devon Rex Cornish Rex) lông xoăn ít rụng, Siamese lông ngắn ít rụng bạn nhé! ALN rụng lông theo mùa nhưng không quá nhiều. Ba Tư Maine Coon rụng nhiều nhất nhé! 🪮', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'bạn ơi cho hỏi mèo bengal giá bao nhiêu vậy', N'Mèo Bengal tại shop giá 7-15 triệu bạn nhé! Lông đốm báo rất đẹp, năng động và thông minh. Bạn muốn xem ảnh các bé đang có không? 🐆', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'tẩy giun và tiêm vaccine nên làm cái nào trước', N'Tẩy giun trước 1-2 tuần rồi mới tiêm vaccine bạn nhé! Giun sán cạnh tranh dinh dưỡng làm hệ miễn dịch yếu, vaccine sẽ kém hiệu quả hơn. Tẩy giun trước là chuẩn nhé! 💊', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'dạy mèo vào lồng vận chuyển thế nào', N'Đặt lồng mở trong nhà thường xuyên để bé quen bạn nhé! Đặt chăn mèo hay đồ chơi quen trong lồng, đôi khi thả snack vào. Mèo tự vào lồng khi thấy đó là nơi an toàn, không ép nhé! 🧳', N'shipping', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có nhớ chủ khi xa không', N'Có bạn nhé! Mèo nhớ chủ lâu dài. Nhiều bé thay đổi hành vi khi chủ đi vắng lâu: bỏ ăn, tìm kiếm, ủ rũ. Khi chủ về thường biểu hiện hào hứng hơn bình thường nhé! 🥰', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Scottish Fold tai cụp sống bao lâu', N'Mèo Scottish Fold tai cụp trung bình sống 12-16 năm với chăm sóc tốt bạn nhé! Giá tại shop 6-12 triệu. Tai cụp đặc trưng điềm tĩnh và quấn chủ. Chăm sóc đúng cách sẽ giúp bé sống thọ nhé! 🎂', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mua mèo ở shop hay nhận cứu hộ tốt hơn', N'Cả hai đều tốt bạn nhé! Mua shop có giống chắc chắn tính cách dự đoán được. Nhận cứu hộ ít tốn kém hơn và cứu một sinh mạng. Quan trọng là bạn sẵn sàng yêu thương bé lâu dài nhé! 💙', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có uy tín không?', N'Meow Garden là shop mèo cảnh và phụ kiện uy tín, cam kết:
✅ Mèo có nguồn gốc rõ ràng tiêm phòng đầy đủ
✅ Sản phẩm chính hãng 100%
✅ Hỗ trợ sau mua 30 ngày miễn phí
✅ Chính sách đổi trả rõ ràng
✅ Chatbot tư vấn 24/7
Ngàn khách hàng đã tin tưởng shop nhé bạn! ⭐', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Ba Tư hay Ragdoll nên chọn giống nào', N'Ba Tư cần chải lông hàng ngày và lau mắt thường xuyên bạn nhé! Ragdoll lông bảo dưỡng ít hơn. Cả hai hiền lành. Ragdoll to hơn và hay theo chủ hơn. Ngân sách tương đương 5-12 triệu nhé! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo cũ hay đánh mèo mới làm sao', N'Bình thường lúc đầu bạn nhé! Mèo cũ cần thời gian chấp nhận bạn mới. Tiếp tục duy trì phòng riêng, tăng dần thời gian gặp có giám sát, thưởng khi hai bé ổn định bên nhau. Quá trình 2-4 tuần là thường nhé! 😼', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'snack nào mèo thích nhất', N'Churu và Ciao là snack được mèo yêu thích nhất bạn nhé! Dạng sệt giàu độ ẩm, mèo háo hức ngay khi nghe mở gói. Rất hữu ích để cho uống thuốc hoặc huấn luyện nhé! 🍡', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Anh Lông Dài ALD trắng có hợp với trẻ em không?', N'Mèo Anh Lông Dài ALD trắng lông xù bồng bềnh cần chải hàng ngày. Giá 5 triệu. Để biết có hợp trẻ em không bạn cho mình biết bé mấy tuổi để tư vấn phù hợp nhé! 👶', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'có thai nuôi mèo có nguy hiểm không', N'An toàn nếu thực hiện đúng bạn nhé! Không dọn khay cát (nguy cơ Toxoplasma), rửa tay sau khi chạm mèo, không để mèo ngủ chung với trẻ sơ sinh. Bác sĩ sản khoa hầu hết đồng ý giữ mèo nhé! 🤰', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'cho mèo ăn tôm được không', N'Tôm luộc chín không gia vị thì mèo ăn được với lượng nhỏ bạn nhé! Tôm cung cấp protein và taurine tốt cho mèo. Tuy nhiên tránh tôm sống (ký sinh trùng), tôm nấu nhiều gia vị muối hành tỏi. Chỉ cho ăn thỉnh thoảng làm đồ thưởng, không thay thức ăn chính nhé! 🍤', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có ăn được cá không', N'Cá hồi hấp chín không gia vị thì tốt cho mèo bạn nhé! Tránh cá sống thường xuyên vì enzyme phá hủy vitamin B1 nhé! 🐟', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị rụng lông xung quanh mắt là sao', N'Rụng lông quanh mắt ở mèo thường do: chảy nước mắt nhiều khiến vùng da ẩm ướt gây kích ứng, nấm da, dị ứng, hoặc viêm da. Với mèo mặt bẹt (Ba Tư, Exotic) thì chảy nước mắt và rụng lông quanh mắt khá phổ biến do cấu trúc mặt. Cần vệ sinh vùng mắt hàng ngày và đưa đi khám nếu nặng hơn nhé! 👁️', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'Balo vận chuyển mèo trong suốt có tốt không?', N'Balo vận chuyển mèo trong suốt rất tốt bạn nhé! An toàn thông thoáng mèo nhìn được ra ngoài không bị stress. Giá 450.000đ tại shop nhé! ⭐', N'shipping', 1, GETUTCDATE(), GETUTCDATE()),
(N'Xem ảnh mèo ở đâu?', N'Bạn có thể xem ảnh tất cả các bé mèo hiện có tại shop ngay trên website Meow Garden nhé. Mỗi bé đều có ảnh rõ nét, thông tin giống, giới tính, tuổi và giá. Bạn cũng có thể nhắn fanpage để được gửi video các bé thực tế trước khi quyết định! 📸', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có bán Gel tiêu búi lông Malta không?', N'Có bạn nhé! Gel tiêu búi lông Malta giá 90.000đ. Giúp mèo tiêu hóa búi lông tránh tắc ruột dùng 3 lần tuần. 🛍️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Anh Lông Ngắn ALN golden sống được bao lâu?', N'Mèo Anh Lông Ngắn ALN golden trung bình sống 12-16 năm nếu được chăm sóc tốt bạn nhé! Giá tại shop 8 triệu. Lông vàng rực rỡ cao cấp đang rất được săn đón nhé! 🎂', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có bán Bát ăn gốm sứ chống gù cổ không?', N'Có bạn nhé! Bát ăn gốm sứ chống gù cổ giá 180.000đ. Đúng tư thế ăn không mùi nhựa dễ vệ sinh. 🛍️', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Abyssinian mèo Abys ăn hạt gì tốt', N'Mèo Abyssinian mèo Abys nên ăn hạt chất lượng phù hợp tuổi bạn nhé! Royal Canin hoặc Minino đều tốt. Giá bé 6-12 triệu. Shop tư vấn thêm nhé! 🌾', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'Gel tiêu búi lông Malta có tốt không?', N'Gel tiêu búi lông Malta rất tốt bạn nhé! Giúp mèo tiêu hóa búi lông tránh tắc ruột dùng 3 lần tuần. Giá 90.000đ tại shop nhé! ⭐', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo nào phù hợp cho người mới nuôi?', N'Cho người mới nuôi mèo, shop gợi ý:
• Mèo ta (mướp): khỏe, ít bệnh, dễ chăm
• Mèo Anh Lông Ngắn: hiền, ít kén chọn thức ăn
• Mèo Ragdoll: cực hiền, ít cào cắn
Tránh Sphynx và Maine Coon vì đòi hỏi chăm sóc đặc biệt hơn nhé bạn! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'dạy mèo không nhảy lên bàn ăn thế nào', N'Đặt đồ vật không dễ chịu lên bàn như giấy bạc hoặc thảm nhựa lật ngược, cung cấp tháp mèo cao để bé leo thay thế bạn nhé! Không để thức ăn trên bàn. Kiên nhẫn và nhất quán là chìa khóa nhé! 🍽️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'đặt hàng như nào', N'Vào website Meow Garden → chọn sản phẩm → thêm giỏ hàng → nhập địa chỉ → chọn COD hoặc chuyển khoản → đặt hàng bạn nhé! 🛒', N'order', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có học được trick không', N'Được bạn nhé! Mèo có thể học: ngồi, đập tay, nằm xuống, nhảy qua vòng, đi cầu thang. Dùng phương pháp clicker training hoặc snack thưởng. Mèo học tốt nhất khi đói nhẹ và tập trung vui vẻ nhé! 🎓', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Ragdoll sống bao lâu', N'Mèo Ragdoll trung bình sống 12-16 năm với chăm sóc tốt bạn nhé! Giá tại shop 6-12 triệu. Siêu hiền mềm xìu khi bế không cào cắn hợp gia đình trẻ em. Chăm sóc đúng cách sẽ giúp bé sống thọ nhé! 🎂', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'vì sao không cho mèo ăn thức ăn thuần chay', N'Mèo là obligate carnivore bắt buộc ăn thịt bạn nhé! Thiếu taurine, arachidonic acid và vitamin A B12 sẵn trong thịt gây bệnh nghiêm trọng. Chế độ ăn thuần chay có thể gây tử vong cho mèo nhé! ⚠️', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay trốn dưới gầm giường là sao', N'Bình thường bạn nhé! Mèo mới về hay trốn do sợ hãi. Để bé tự ra từ từ, đừng ép. Đặt thức ăn gần chỗ trốn. Hầu hết mèo ra chơi sau 3-7 ngày làm quen nhé! 🏠', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo thuần chủng và mèo lai khác gì', N'Mèo thuần chủng có nguồn gốc rõ ràng tính cách ổn định hơn bạn nhé! Mèo lai thường khỏe mạnh hơn nhờ đa dạng gen. Mèo ta mướp lai là lựa chọn tốt giá rẻ cho người mới nuôi nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'phòng bệnh cho mèo tốn bao nhiêu một năm', N'Vaccine + tẩy giun + phòng ký sinh trùng khoảng 500k-1 triệu một năm bạn nhé! Rẻ hơn nhiều so với điều trị khi bệnh. Đầu tư phòng bệnh luôn tiết kiệm hơn chữa bệnh nhé! 💰', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo nhìn chằm chằm vào tường là bị gì?', N'Thường là do mèo nghe hoặc ngửi thấy côn trùng, chuột hoặc vật nhỏ trong tường mà mắt người không nhìn thấy bạn nhé. Thính giác và khứu giác mèo nhạy hơn người rất nhiều. Ít gặp hơn nhưng cũng cần chú ý nếu kèm theo lảo đảo hoặc hành vi bất thường thì nên đi khám nhé! 👂', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'giống mèo nào phù hợp người lần đầu nuôi', N'Tốt nhất cho người mới: ALN xám xanh hiền lành ít kêu, Mèo ta mướp khỏe mạnh giá phải chăng, Scottish Fold điềm tĩnh bạn nhé! Tránh Bengal (cần nhiều kích thích) và Siamese (kêu nhiều) cho người mới nhé! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo có nhận ra chủ không', N'Rất nhận ra bạn nhé! Mèo nhận ra qua giọng nói, mùi cơ thể và bước chân. Nghiên cứu chứng minh mèo nghe tiếng chủ và phân biệt được với người lạ nhưng thường không phản ứng rõ ràng vì tính độc lập nhé! 🥰', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'con mèo dễ thương quá', N'Cảm ơn bạn nhé! 🐱 Mèo nhà mình chắc đang ngủ cực kute đây. Bạn đang có bé mèo nào không hay đang tìm mua? 😊', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Anh Lông Ngắn ALN bicolor sống được bao lâu?', N'Mèo Anh Lông Ngắn ALN bicolor trung bình sống 12-16 năm nếu được chăm sóc tốt bạn nhé! Giá tại shop 6.5 triệu. Lông chia 2 màu đối xứng rất đẹp tính cách điềm tĩnh nhé! 🎂', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Birman mèo thánh sống bao lâu', N'Mèo Birman mèo thánh trung bình sống 12-16 năm với chăm sóc tốt bạn nhé! Giá tại shop 5-10 triệu. Lông xù nhẹ mặt hiền đặc biệt đốm trắng ở 4 bàn chân rất hiền không hung hăng nhé! 🎂', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo già ngủ nhiều có sao không', N'Mèo già ngủ 18-20h ngày là bình thường bạn nhé! Chỉ lo nếu kèm bỏ ăn, sụt cân hoặc không phản ứng khi gọi. Tạo chỗ ngủ êm ấm dễ lên xuống cho bé nhé! 😴', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Mèo ta mướp có đặc điểm gì?', N'Mèo Mèo ta mướp: khỏe mạnh thích nghi tốt ít bệnh phù hợp người mới nuôi. Giá 500k-2 triệu tại shop nhé bạn! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo sống được bao nhiêu năm', N'Mèo nhà trung bình 12-18 năm. Mèo trong nhà sống thọ hơn. Chăm sóc tốt nhiều bé sống đến 15-20 năm nhé bạn! 🎂', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N't muốn mua mèo cho con tôi 5 tuổi', N'Cho bé 5 tuổi, shop gợi ý những giống hiền nhất:
🐱 Ragdoll: siêu hiền, không cào cắn, rất hợp trẻ em
🐱 Mèo Anh Lông Ngắn: điềm tĩnh, không hung hăng
🐱 Mèo ta mướp: thích nghi tốt, khỏe mạnh, giá mềm
Cả ba giống đều an toàn với trẻ nhỏ. Bạn muốn tìm hiểu thêm về giống nào? 🐾', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
