(N'Tại sao mèo lại cào đồ đạc?', N'Mèo cào đồ đạc để: mài móng vuốt, đánh dấu lãnh thổ bằng tuyến mùi ở chân, và căng giãn cơ bắp. Đây là hành vi bản năng không thể ngăn hoàn toàn. Giải pháp: mua trụ cào móng hoặc thảm cào đặt gần chỗ bé hay cào, dán băng keo hai mặt vào đồ vật bé không được cào nhé! 🪵', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'người dị ứng mèo có nuôi được không', N'Được trong một số trường hợp bạn nhé! Triệt sản mèo giảm 50% protein gây dị ứng. Tắm mèo thường xuyên, lọc không khí HEPA, không cho mèo vào phòng ngủ, rửa tay sau khi chạm. Thử ở gần mèo trước khi mua nhé! 🤧', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'dạy mèo đập tay thế nào', N'Cầm snack, đưa tay ra gần bàn chân trước bé, nói paw, khi bé chạm tay thì thưởng ngay bạn nhé! Mèo học nhanh nếu thưởng kịp thời trong vòng 1-2 giây. Kiên nhẫn luyện mỗi ngày nhé! 🐾', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo bị bọ chét làm sao trị?', N'Trị bọ chét mèo: dùng thuốc nhỏ gáy (Frontline, Advocate) hoặc vòng cổ chống ký sinh trùng. Đồng thời vệ sinh toàn bộ chỗ mèo nằm, giặt chăn đệm nước nóng. Cần trị đồng thời mèo và môi trường vì 95% bọ chét sống trong môi trường không phải trên mèo nhé! 🦟', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị táo bón phải làm sao', N'Tăng độ ẩm bằng pate và súp gà, đảm bảo uống đủ nước, dùng gel tiêu búi lông, tăng vận động bạn nhé. Táo bón hơn 3 ngày thì đưa đi khám ngay! 💊', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay kêu trước khi nôn là sao', N'Kêu hú hoặc gào trước khi nôn là bình thường bạn nhé! Cơ thể báo hiệu trước khi co bóp dạ dày. Nôn 1-2 lần với búi lông không đáng lo. Nôn nhiều không có búi lông thì cần khám nhé! 🐱', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'ship lâu quá', N'Xin lỗi bạn vì sự chờ đợi nhé! Bạn cho mình mã vận đơn để mình kiểm tra tình trạng giao hàng giúp bạn nhé! 🚚', N'shipping', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Norwegian Forest Cat mèo rừng Na Uy giá bao nhiêu?', N'Mèo Norwegian Forest Cat mèo rừng Na Uy tại shop giá 10-20 triệu bạn nhé! Lông dày dài chịu lạnh tốt cơ thể to khỏe thích leo trèo. 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo nào sống thọ nhất theo giống', N'Siamese và Ragdoll nổi tiếng sống thọ 15-20 năm bạn nhé! Russian Blue và Burmese cũng sống thọ trung bình 15-18 năm. Maine Coon trung bình 12-15 năm. Chăm sóc tốt quan trọng hơn giống nhé! 🎂', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Burmese mèo Miến Điện nuôi có khó không?', N'Mèo Burmese mèo Miến Điện mắt vàng to đẹp thân thiện hay nói chuyện thích người. Giá 5-10 triệu. Về độ khó chăm sóc hãy hỏi thêm mình tư vấn cụ thể nhé bạn! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay rúc đầu vào nách là sao', N'Bé thích mùi của bạn và tìm hơi ấm bạn nhé! Nách có tuyến mồ hôi tiết mùi đặc trưng mà mèo nhận ra. Đây là dấu hiệu bé rất gắn bó và coi bạn là gia đình nhé! 🥰', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'bán hamster không', N'Shop Meow Garden chỉ chuyên mèo cảnh thôi bạn nhé! Không có hamster hay thú cưng khác. Tư vấn về mèo thì mình sẵn sàng nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo ăn dầu mỡ nhiều có sao không', N'Dầu mỡ nhiều gây tiêu chảy và viêm tụy ở mèo bạn nhé! Thức ăn chiên rán nhiều dầu không phù hợp. Omega 3 từ dầu cá liều nhỏ thì tốt, còn dầu ăn thông thường thì không nhé! ⚠️', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Birman mèo thánh có dễ chăm không', N'Mèo Birman mèo thánh lông xù nhẹ mặt hiền đặc biệt đốm trắng ở 4 bàn chân rất hiền không hung hăng. Giá 5-10 triệu. Nhìn chung đây là giống phù hợp cho người yêu mèo bạn nhé! Shop tư vấn cụ thể hơn nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'chi phí nuôi mèo 1 năm tốn bao nhiêu', N'Chi phí 1 năm tầm 7-10 triệu gồm: thức ăn 4-5 triệu, cát 2-3 triệu, khám định kỳ vaccine 1-2 triệu, đồ chơi phụ kiện bạn nhé! Cộng thêm chi phí bất thường nếu bệnh. Có thể mua bảo hiểm thú cưng để an tâm hơn nhé! 💰', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo mấy tháng tuổi thì triệt sản?', N'Thời điểm lý tưởng để triệt sản là 5-6 tháng tuổi - trước khi mèo đến tuổi động dục lần đầu. Mèo cái nên triệt sản sớm để giảm nguy cơ ung thư vú. Mèo đực triệt sản giúp bớt hung hăng và xịt nước tiểu đánh dấu nhé! ✂️', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay chạy đêm là sao', N'Mèo hoạt động nhiều vào chạng vạng tối và sáng sớm là bản năng bạn nhé! Chơi đùa nhiều buổi tối để bé mệt trước giờ ngủ nhé! 🌙', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'website có bảo mật không khi thanh toán', N'Website Meow Garden dùng HTTPS và cổng thanh toán bảo mật chuẩn PCI bạn nhé! Thông tin thẻ không lưu tại shop. Thanh toán COD hoặc chuyển khoản nếu muốn tuyệt đối an toàn nhé! 🔒', N'order', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị ốm dấu hiệu gì', N'Dấu hiệu mèo ốm: bỏ ăn hơn 24h, nôn mửa liên tục, tiêu chảy, lờ đờ không hoạt động, lông xù không tự chải, đi tiểu bất thường. Thấy 2-3 dấu hiệu cùng lúc thì đi khám ngay nhé bạn! 🏥', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Bán mèo Anh Lông Dài ALD trắng không?', N'Có bạn nhé! Mèo Anh Lông Dài ALD trắng giá 5 triệu. Lông xù bồng bềnh cần chải hàng ngày. Liên hệ shop để xem bé nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Mèo ta mướp ăn hạt gì tốt', N'Mèo Mèo ta mướp nên ăn hạt chất lượng phù hợp tuổi bạn nhé! Royal Canin có dòng riêng cho một số giống. Minino giá phải chăng phù hợp hàng ngày. Giá bé 500k-2 triệu tại shop. Shop tư vấn thêm nhé! 🌾', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'âm thanh nhạc có ảnh hưởng đến mèo không', N'Có bạn nhé! Mèo thích nhạc nhẹ không quá ồn, tần số cao. Nhạc viết riêng cho mèo (music for cats) đã được nghiên cứu giảm stress khi chủ vắng nhà. Tránh nhạc ầm ĩ gần chỗ mèo nhé! 🎵', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Tôi muốn mua mèo Ragdoll', N'Mèo Ragdoll tại shop giá 6-12 triệu bạn nhé! Siêu hiền mềm xìu khi bế không cào cắn hợp gia đình trẻ em. Bạn muốn biết thêm không? 😊', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mình nghĩ lại đã', N'Không vội bạn nhé! Quyết định nuôi mèo nên suy nghĩ kỹ. Khi nào sẵn sàng mình tư vấn tiếp nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo hay đẩy đồ ăn ra khỏi bát là sao', N'Mèo không thích râu chạm vào thành bát (whisker fatigue) bạn nhé! Thử bát rộng và nông hơn. Bát gốm sứ chống gù cổ của shop vừa đúng tư thế vừa đủ rộng cho râu bé thoải mái nhé! 🍽️', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị bỏ lại một mình cả ngày có sao không', N'Mèo có thể ở nhà một mình trong ngày được bạn nhé, khác với chó. Đảm bảo có đủ thức ăn nước uống, khay cát sạch và đồ chơi để bé tự giải trí. Nếu vắng quá 8-10 tiếng thường xuyên thì nên nghĩ đến việc nuôi 2 mèo cho bé có bạn. Khi về nhà nhớ dành thời gian chơi bù với bé nhé! 🏠', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N't ở hcm mua được không', N'Hoàn toàn được bạn nhé! Shop có showroom và giao hàng trong TP.HCM 1-2 ngày làm việc. Đơn từ 500k miễn phí ship nội thành HCM. Mèo cảnh shop hỗ trợ vận chuyển trong TP.HCM hoặc bạn đến trực tiếp xem bé nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo vừa bị chó cắn phải làm sao', N'Đưa đến bác sĩ thú y ngay dù vết thương nhỏ bạn nhé! Vết cắn chó rất dễ nhiễm khuẩn và tổn thương nội tạng bên trong dù bên ngoài trông nhỏ. Cầm máu bằng vải sạch trong khi di chuyển nhé! 🚨', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Nhà cây cho mèo cat tree 120cm có tốt không?', N'Nhà cây cho mèo cat tree 120cm rất tốt bạn nhé! Đáp ứng nhu cầu leo trèo cào móng và ngủ nghỉ giảm phá đồ trong nhà. Giá 850.000đ tại shop nhé! ⭐', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo gừ gừ có ý nghĩa gì', N'Thường nghĩa là mèo hài lòng khi được vuốt ve. Nhưng mèo cũng gừ khi đang đau để tự trấn an. Phân biệt qua ngôn ngữ cơ thể nhé bạn! 💕', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Nhà cây cho mèo cat tree 120cm giá bao nhiêu?', N'Nhà cây cho mèo cat tree 120cm tại shop giá 850.000đ bạn nhé! Đáp ứng nhu cầu leo trèo cào móng và ngủ nghỉ giảm phá đồ trong nhà. 🛍️', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị chướng bụng là sao', N'Bụng mèo căng phồng bất thường có thể do: đầy hơi sau khi ăn nhanh, tích nước trong bụng (ascites - dấu hiệu bệnh nghiêm trọng), hoặc có khối u. Đầy hơi nhẹ sau ăn tự hết. Nếu bụng căng cứng lâu không xẹp kèm khó thở lờ đờ thì cần đưa đi khám khẩn cấp ngay nhé bạn! 🏥', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'maine coon nặng bao nhiêu', N'Maine Coon là giống mèo to nhất thế giới bạn nhé! Mèo đực Maine Coon nặng 6-11kg khi trưởng thành, mèo cái 4-7kg. Cần 3-5 năm để đạt kích thước tối đa. Dù to như mèo rừng nhưng Maine Coon tính cách rất hiền lành và thân thiện! 🦁', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'giao sai hàng rồi kìa', N'Xin lỗi bạn rất nhiều nhé! 🙏 Bạn chụp ảnh hàng nhận được và nhắn kèm mã đơn cho shop. Shop sẽ gửi đúng hàng và chịu toàn bộ phí vận chuyển đổi nhé!', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'shop hỗ trợ sau mua trong bao lâu', N'Meow Garden hỗ trợ tư vấn sau mua mèo 30 ngày miễn phí bạn nhé! Tư vấn về chế độ ăn hành vi sức khỏe ban đầu. Nếu bé bệnh trong 72h đầu shop hỗ trợ 100% chi phí khám nhé! 💚', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'app Meow Garden có không', N'Hiện chưa có app riêng bạn nhé! Truy cập website trên điện thoại rất mượt mà. Lưu vào màn hình chính để dùng như app bạn nhé! 📱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo bị hắt hơi liên tục là sao', N'Hắt hơi 1-2 lần bình thường do bụi. Liên tục kèm nước mũi có thể do cảm mèo. Kéo dài hơn 2 ngày hoặc dịch mũi vàng xanh thì đi khám nhé bạn! 🤧', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Nhận hàng sai thì xử lý thế nào?', N'Vui lòng chụp ảnh sản phẩm nhận được và liên hệ shop trong vòng 24 giờ sau khi nhận hàng. Shop sẽ xác minh và gửi đúng sản phẩm kèm chịu toàn bộ phí vận chuyển đổi hàng cho bạn nhé! 📸', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'tôi muốn trả lại mèo vì không hợp', N'Mèo cần thời gian thích nghi bạn nhé! 🐱 Nhiều người nghĩ không hợp trong 2 tuần đầu nhưng sau 1 tháng lại yêu không rời được. Thử đủ 4 tuần trước khi quyết định. Shop sẵn sàng tư vấn hành vi giúp bạn nhé! 😊', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo có ăn thức ăn cho chó không?', N'Không nên bạn nhé! Thức ăn cho chó thiếu taurine và arachidonic acid mà mèo bắt buộc phải có từ thức ăn vì không tự tổng hợp được. Thiếu taurine gây mù và bệnh tim ở mèo. Cho mèo ăn thức ăn chó lâu dài rất nguy hiểm nhé! 🚫', N'product', 1, GETUTCDATE(), GETUTCDATE()),
(N'Norwegian Forest Cat mèo rừng Na Uy có phù hợp người mới nuôi không', N'Mèo Norwegian Forest Cat mèo rừng Na Uy lông dày dài chịu lạnh tốt cơ thể to khỏe thích leo trèo. Giá 10-20 triệu. Hãy liên hệ shop để được tư vấn phù hợp với hoàn cảnh của bạn nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo con bao lâu thì lớn hoàn toàn', N'Mèo lớn hoàn toàn lúc 12-18 tháng bạn nhé! Một số giống to như Maine Coon cần 3-5 năm. Chuyển sang thức ăn mèo trưởng thành lúc 12 tháng. Triệt sản vẫn nên làm trước 12 tháng nhé! 🎂', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'cái kia bao nhiêu', N'Bạn đang hỏi về sản phẩm hoặc mèo nào vậy? Mình cần biết tên cụ thể để báo giá chính xác nhé! 😊', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo thích nằm trên người là sao?', N'Mèo nằm trên người vì: cơ thể người tỏa nhiệt ấm áp mèo thích, cảm thấy an toàn và được bảo vệ, mùi chủ quen thuộc, đây là cách thể hiện tình cảm và tin tưởng. Mèo nằm lên người là dấu hiệu bé coi bạn là thành viên tin cậy trong bầy của mình đấy! Đáng yêu lắm nhé! 🥰', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'vaccine 3 trong 1 cho mèo là gì', N'Vaccine FVRCP hay 3 in 1 phòng 3 bệnh: Panleukopenia virus mèo viêm ruột rất nguy hiểm, Herpesvirus cúm mèo, Calicivirus cúm mèo bạn nhé! Đây là vaccine cốt lõi mọi mèo cần tiêm nhé! 💉', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'Có nên nuôi 2 mèo không?', N'Nuôi 2 mèo giúp bé đỡ cô đơn, vận động nhiều hơn và ít phá đồ hơn khi bạn vắng nhà. Tuy nhiên cần thả quen dần không thả 2 bé vào cùng phòng ngay, cần đủ tài nguyên (2 khay cát, 2 bát ăn) và chuẩn bị chi phí thú y nhân đôi nhé! 🐱🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Russian Blue có dễ chăm không', N'Mèo Russian Blue lông xám xanh ánh bạc nhút nhát lúc đầu nhưng trung thành. Giá 6-10 triệu. Nhìn chung đây là giống cần chú ý một chút bạn nhé! Liên hệ shop để tư vấn cụ thể nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'maine coon to nhất thế giới không', N'Đúng vậy bạn nhé! Maine Coon là giống mèo nhà lớn nhất thế giới. Mèo đực đạt 8-12kg mèo cái 4-7kg. Cần 3-5 năm để đạt kích thước tối đa. Giá 8-18 triệu tại shop nhé! 🦁', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Scottish Fold tai cụp bao lâu tắm một lần', N'Mèo Scottish Fold tai cụp tắm 1 lần tháng là đủ bạn nhé! Tai cụp đặc trưng điềm tĩnh và quấn chủ. Lông ngắn dễ chăm hơn. Giá bé 6-12 triệu nhé! 🛁', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'lý do nên nuôi mèo', N'Nuôi mèo: giảm stress và huyết áp, đồng hành tinh thần, không cần đi dạo như chó, tự vệ sinh sạch sẽ, nghiên cứu khoa học chứng minh tốt cho sức khỏe tâm thần! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Munchkin chân ngắn ăn hạt gì tốt', N'Mèo Munchkin chân ngắn nên ăn hạt chất lượng phù hợp tuổi bạn nhé! Royal Canin có dòng riêng cho một số giống. Minino giá phải chăng phù hợp hàng ngày. Giá bé 5-9 triệu tại shop. Shop tư vấn thêm nhé! 🌾', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo bị nấm da làm sao?', N'Nấm da mèo biểu hiện: lông rụng thành hình tròn, da đỏ ngứa, có vảy. Lây được cho người và mèo khác nên cần cách ly bé bệnh ngay. Điều trị bằng thuốc bôi hoặc dầu gội kháng nấm theo chỉ định bác sĩ. Tắm nắng và giữ môi trường khô ráo giúp phòng ngừa nấm nhé! 🏥', N'cat_care', 1, GETUTCDATE(), GETUTCDATE()),
(N'mèo Burmese mèo Miến Điện sống bao lâu', N'Mèo Burmese mèo Miến Điện trung bình sống 12-16 năm với chăm sóc tốt bạn nhé! Giá tại shop 5-10 triệu. Mắt vàng to đẹp thân thiện hay nói chuyện thích người nhé! 🎂', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'bao nhiêu mèo thì quá nhiều', N'Không có con số tuyệt đối bạn nhé! Tùy diện tích nhà và khả năng chăm sóc. Thường mỗi người nên chăm tối đa 3-5 mèo để đảm bảo chất lượng cuộc sống cho mỗi bé. Quá nhiều mèo một chỗ gây stress và bệnh tật nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Shop có mèo Mèo ta mướp không?', N'Có bạn nhé! Mèo Mèo ta mướp tại shop giá 500k-2 triệu. Khỏe mạnh thích nghi tốt ít bệnh phù hợp người mới nuôi. Bạn muốn biết thêm không? 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Tại sao mèo hay gù lưng?', N'Mèo gù lưng khi: sợ hãi và muốn trông to hơn để dọa đối thủ, hoặc khi đang chơi đùa vui vẻ. Nếu mèo gù lưng kèm theo lông dựng đứng và kêu gừ thì đang sợ hoặc hung hăng. Nếu gù nhẹ khi chạy nhảy thì đang vui chơi thôi bạn nhé! 🐱', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'có nên cho mèo mới về tắm ngay không', N'Không nên tắm trong 1-2 tuần đầu bạn nhé! Bé đang stress và cần thời gian ổn định. Tắm gây thêm stress và dễ cảm lạnh. Chờ bé ăn ngủ bình thường mới tắm nhé! 🛁', N'general', 1, GETUTCDATE(), GETUTCDATE()),
(N'Mèo Maine Coon tính cách thế nào?', N'Mèo Maine Coon giống to nhất thế giới rất thông minh và thân thiện. Giá 8-18 triệu rất phù hợp nhé bạn! 🐱', N'cat', 1, GETUTCDATE(), GETUTCDATE()),
